<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tests | Lab Admin</title><style>body{margin:0;background:#f1f7fb;color:#12304c;font-family:Arial,sans-serif}.wrap{max-width:1120px;margin:42px auto;padding:0 20px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.back,.edit{color:#2476c7;text-decoration:none;font-weight:bold}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#fff;border:1px solid #dce9f0;border-radius:14px;padding:24px;box-shadow:0 8px 22px #dce8ef}.field{margin:15px 0}.field label{display:block;margin-bottom:6px;font-size:13px;font-weight:bold}input,textarea,select{width:100%;padding:11px;box-sizing:border-box;border:1px solid #cbdce7;border-radius:8px;font:inherit}textarea{min-height:100px}button{border:0;border-radius:8px;padding:10px 14px;background:#16b9a7;color:#fff;font-weight:bold;cursor:pointer}.delete{background:#dc4b52;margin-left:8px}.ok{margin-bottom:18px;padding:12px;border-radius:8px;background:#def9f2;color:#087a6b}.item{padding:15px 0;border-bottom:1px solid #e1ecf2}.item:last-child{border:0}.item h3{margin:0 0 5px}.item p{margin:0;color:#668099;line-height:1.5}.tag{display:inline-block;margin-top:7px;padding:4px 8px;border-radius:12px;background:#e5f8f3;color:#068b78;font-size:11px;font-weight:bold}.actions{margin-top:10px}.actions form{display:inline}.test-list{max-height:650px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#16b9a7 #edf4f8;padding-right:8px}.test-list::-webkit-scrollbar{width:8px}.test-list::-webkit-scrollbar-track{background:#edf4f8;border-radius:20px}.test-list::-webkit-scrollbar-thumb{background:#16b9a7;border-radius:20px}.test-list-head{position:sticky;top:-24px;z-index:2;margin:-24px -24px 14px;padding:24px;background:#fff;border-bottom:1px solid #e1ecf2}.test-list-head h2{margin:0 0 14px}.test-search{position:relative}.test-search input{padding-left:37px;background:#f7fbfd}.test-search span{position:absolute;left:13px;top:10px;color:#668099}@media(max-width:700px){.grid{grid-template-columns:1fr}.top{flex-direction:column;align-items:flex-start}.test-list{max-height:560px}}</style></head><body><main class="wrap"><header class="top"><div><h1>Tests</h1><p>Create, edit, or remove tests assigned to services.</p></div><a class="back" href="{{ route('admin.dashboard') }}">← Dashboard</a></header>@if(session('success'))<div class="ok">{{ session('success') }}</div>@endif<div class="grid"><section class="card"><h2>Add Test</h2><form method="post" action="{{ route('admin.tests.store') }}" enctype="multipart/form-data">@csrf<div class="field"><label>Assign to service</label><select name="service_id" required><option value="">Select service</option>@foreach($services as $service)<option value="{{ $service->id }}">{{ $service->name }}</option>@endforeach</select></div><div class="field"><label>Test name</label><input name="name" required></div><div class="field"><label>Card heading</label><input name="heading"></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Test photo</label><input type="file" name="image" accept="image/png,image/jpeg,image/webp"></div><button>Add test</button></form></section><section class="card test-list"><div class="test-list-head"><h2>Assigned Tests <small style="font-size:12px;color:#668099;font-weight:normal">({{ $tests->count() }})</small></h2><div class="test-search"><span>⌕</span><input id="test-search" type="search" placeholder="Search by test name or service…"></div></div><div id="tests-results">@forelse($tests as $test)<article class="item test-item" data-search="{{ strtolower(($test->heading ?: $test->name).' '.$test->description.' '.$test->service_name) }}"><h3>{{ $test->heading ?: $test->name }}</h3><p>{{ $test->description ?: 'No description added.' }}</p><span class="tag">{{ $test->service_name }}</span><div class="actions"><a class="edit" href="{{ route('admin.tests.edit',$test->id) }}">Edit</a><form method="post" action="{{ route('admin.tests.delete',$test->id) }}" onsubmit="return confirm('Delete this test?')">@csrf<button class="delete">Delete</button></form></div></article>@empty<p>No tests added yet.</p>@endforelse</div><p id="no-tests" style="display:none;color:#668099;text-align:center;padding:20px">No matching tests found.</p></section></div></main><script>document.getElementById('test-search').addEventListener('input',function(){var q=this.value.toLowerCase().trim(),shown=0;document.querySelectorAll('.test-item').forEach(function(item){var match=item.dataset.search.indexOf(q)!==-1;item.style.display=match?'block':'none';if(match)shown++;});document.getElementById('no-tests').style.display=shown?'none':'block';});</script></body></html>
